fn smallest_list_length(list: &Vec<Vec<i32>>) -> usize {
    // Since `list` is guaranteed to be non-empty, calling `min().unwrap()` is safe.
    list.iter()
        .map(|inner| inner.len())
        .min()
        .unwrap()
}

